//! The Ising category over `Q(zeta_16)`: pinned exact data, Clifford-type braid gates,
//! an independent Majorana-algebra witness for the braid generators, and negative controls
//! whose violated index tuples were computed independently (separate exact-arithmetic
//! implementation).
//!
//! What is and is not stated: the exact group generated by the braid generators on four
//! sigma anyons with total charge 1 is finite, with 192 elements (24 modulo scalars, the
//! single-qubit Clifford group), and does not contain the T gate. That is a statement about
//! this finite exact closure; nothing here says anything about any material or device.
//!
//! AuthorityEffect: None.

use linear_algebra::backend::basic_matrix::BasicMatrix;
use linear_algebra::exact_field::matrix;
use core_fusion_categories::braid_group::{braid_relation_defects, group_closure, ClosureOutcome};
use core_fusion_categories::braided::{BraidedFusionCategory, HexagonForm, RibbonFusionCategory};
use core_fusion_categories::catalog;
use core_fusion_categories::error::FusionError;
use core_fusion_categories::fusion_category::{CategoryDefect, FusionCategory};
use core_fusion_categories::modular::ModularData;
use core_fusion_categories::scalar::sqrt_two;
use core_number_theory::cyclotomic_field::Cyclotomic;
use core_number_theory::rational::{rq, Rational};
use core_number_theory::scalar::from_i64;

type K = Cyclotomic<16>;

fn z(k: i64) -> K {
    K::zeta(k)
}

fn i_unit() -> K {
    z(4)
}

fn q(n: i64, d: i64) -> Rational {
    rq(n, d)
}

fn sorted<const N: usize>(mut labels: Vec<[usize; N]>) -> Vec<[usize; N]> {
    labels.sort();
    labels
}

fn ising() -> RibbonFusionCategory<K> {
    catalog::ising::<K>().unwrap()
}

fn inverse_sqrt_two() -> K {
    sqrt_two::<K>().unwrap().inverse().unwrap()
}

fn s_gate() -> BasicMatrix<K> {
    matrix::diagonal(&[K::one(), i_unit()])
        .map_err(FusionError::from)
        .unwrap()
}

fn hadamard() -> BasicMatrix<K> {
    let a = inverse_sqrt_two();
    matrix::from_rows(vec![vec![a.clone(), a.clone()], vec![a.clone(), a.neg()]])
        .map_err(FusionError::from)
        .unwrap()
}

#[test]
fn ising_has_the_pinned_exact_data() {
    let ising = ising();
    let sqrt2 = sqrt_two::<K>().unwrap();
    assert_eq!(sqrt2, z(2).add(&z(-2)), "sqrt 2 = zeta_16^2 + zeta_16^-2");
    assert_eq!(sqrt2.mul(&sqrt2), from_i64::<K>(2));
    assert_eq!(ising.dimensions(), &[K::one(), sqrt2.clone(), K::one()]);
    assert_eq!(
        ising.twists(),
        &[K::one(), z(1), K::one().neg()],
        "theta = (1, zeta_16, -1)"
    );
    // F^{sigma sigma sigma}_sigma = (1/sqrt 2) [[1, 1], [1, -1]] on (1, psi); the others are -1 or 1.
    let a = inverse_sqrt_two();
    let f = |labels: [usize; 4], e: usize, g: usize| ising.category().f_entry(labels, e, g);
    assert_eq!(f([1, 1, 1, 1], 0, 0), a);
    assert_eq!(f([1, 1, 1, 1], 0, 2), a);
    assert_eq!(f([1, 1, 1, 1], 2, 0), a);
    assert_eq!(f([1, 1, 1, 1], 2, 2), a.neg());
    assert_eq!(f([1, 2, 1, 2], 1, 1), K::one().neg());
    assert_eq!(f([2, 1, 2, 1], 1, 1), K::one().neg());
    // R^{ss}_1 = zeta_16^-1, R^{ss}_psi = zeta_16^3, R^{s psi}_s = R^{psi s}_s = -i, R^{psi psi}_1 = -1.
    let r = |labels: [usize; 3]| ising.braided().r_entry(labels);
    assert_eq!(r([1, 1, 0]), z(-1));
    assert_eq!(r([1, 1, 2]), z(3));
    assert_eq!(r([1, 2, 1]), i_unit().neg());
    assert_eq!(r([2, 1, 1]), i_unit().neg());
    assert_eq!(r([2, 2, 0]), K::one().neg());
    // D^2 = 4, p_+ = 2 zeta_16, c = 1/2.
    assert_eq!(ising.global_dimension_squared(), from_i64::<K>(4));
    assert_eq!(ising.gauss_sum(), from_i64::<K>(2).mul(&z(1)));
    // The pentagon, both hexagons, the dimensions and the balancing relation all hold.
    assert_eq!(ising.category().pentagon_defects(), vec![]);
    assert!(ising
        .braided()
        .hexagon_defects(HexagonForm::Direct)
        .is_empty());
    assert!(ising
        .braided()
        .hexagon_defects(HexagonForm::Mirror)
        .is_empty());
    assert!(
        ising.category().is_unitary().unwrap(),
        "the standard Ising F-matrices are unitary"
    );
}

#[test]
fn ising_modular_data_central_charge_and_ground_states_are_exact() {
    let ising = ising();
    let modular = ModularData::verified(&ising).unwrap();
    let sqrt2 = sqrt_two::<K>().unwrap();
    // S~ = [[1, sqrt2, 1], [sqrt2, 0, -sqrt2], [1, -sqrt2, 1]].
    let expected = [
        [K::one(), sqrt2.clone(), K::one()],
        [sqrt2.clone(), K::zero(), sqrt2.neg()],
        [K::one(), sqrt2.neg(), K::one()],
    ];
    for (a, row) in expected.iter().enumerate() {
        for (b, value) in row.iter().enumerate() {
            assert_eq!(&modular.s_tilde().get(a, b).unwrap(), value, "S~[{a}][{b}]");
        }
    }
    // Gauss-Milgram: p_+^2 / D^2 = zeta_16^2 = zeta_8, so c = 1/2 modulo 4; with D = 2 in the
    // field and positive, p_+ / D = zeta_16 gives c = 1/2 modulo 8.
    assert_eq!(modular.p_plus(), &from_i64::<K>(2).mul(&z(1)));
    assert_eq!(modular.central_charge_mod_4().unwrap(), q(1, 2));
    assert_eq!(
        modular.central_charge_mod_8(&from_i64::<K>(2)).unwrap(),
        q(1, 2)
    );
    // Genus-g ground-state degeneracy: 3 on the torus, 10 on genus 2, 36 on genus 3.
    let counts: Vec<String> = (0..4)
        .map(|g| modular.ground_state_degeneracy(g).unwrap().to_string())
        .collect();
    assert_eq!(counts, ["1", "3", "10", "36"]);
    // Frobenius-Schur indicators: sigma and psi are +1, from the F-symbols and from Bantay.
    for a in 0..3 {
        assert_eq!(modular.frobenius_schur_indicator(a), Ok(1));
        assert_eq!(
            ising
                .category()
                .frobenius_schur_indicator(a, ising.dimensions()),
            Ok(Some(1))
        );
    }
    // The dimensions are exactly the Frobenius-Perron dimensions (sqrt 2 > 0 decided exactly).
    assert_eq!(ising.dimensions_are_frobenius_perron(), Ok(true));
    // D = -2 has the right square but the wrong sign.
    assert_eq!(
        modular.central_charge_mod_8(&from_i64::<K>(-2)),
        Err(FusionError::Modular(
            core_fusion_categories::modular::ModularDefect::NonPositiveDimension
        ))
    );
}

#[test]
fn the_other_spherical_structure_of_the_same_braided_category_has_central_charge_nine_halves() {
    // d_sigma = -sqrt 2 is a second valid ribbon structure on the same F- and R-symbols (a
    // character of the ring consistent with the F-symbols): theta_sigma = -zeta_16, c = 9/2.
    let ising = ising();
    let sqrt2 = sqrt_two::<K>().unwrap();
    let other = RibbonFusionCategory::try_new(
        ising.braided().clone(),
        vec![K::one(), sqrt2.neg(), K::one()],
    )
    .unwrap();
    assert_eq!(other.twists()[1], z(1).neg());
    assert_eq!(other.dimensions_are_frobenius_perron(), Ok(false));
    let modular = ModularData::verified(&other).unwrap();
    assert_eq!(
        modular.central_charge_mod_8(&from_i64::<K>(2)).unwrap(),
        q(9, 2)
    );
    assert_eq!(modular.central_charge_mod_4().unwrap(), q(1, 2));
    // sigma then has Frobenius-Schur indicator -1 in this structure.
    assert_eq!(modular.frobenius_schur_indicator(1), Ok(-1));
}

#[test]
fn the_conjugate_ising_category_has_central_charge_minus_one_half() {
    let ising = ising();
    let mirror = ising.complex_conjugate().unwrap();
    assert_eq!(mirror.twists()[1], z(-1));
    let modular = ModularData::verified(&mirror).unwrap();
    assert_eq!(modular.central_charge_mod_4().unwrap(), q(7, 2));
    assert_eq!(
        modular.central_charge_mod_8(&from_i64::<K>(2)).unwrap(),
        q(15, 2)
    );
    // The same model in a bigger field (Q(zeta_32) contains zeta_16) has the same data.
    let bigger = catalog::ising::<Cyclotomic<32>>().unwrap();
    let big_modular = ModularData::verified(&bigger).unwrap();
    assert_eq!(
        big_modular
            .central_charge_mod_8(&from_i64::<Cyclotomic<32>>(2))
            .unwrap(),
        q(1, 2)
    );
}

#[test]
fn a_perturbed_ising_f_symbol_fails_the_pentagon_at_the_twelve_independent_tuples() {
    let ising = ising();
    // F^{sss}_s[psi, psi] = -1/sqrt 2  ->  +1/sqrt 2.
    let f = ising
        .category()
        .f_symbols()
        .with_entry([1, 1, 1, 1], 2, 2, inverse_sqrt_two())
        .unwrap();
    let category = FusionCategory::new(ising.ring().clone(), f).unwrap();
    // The perturbed block [[a, a], [a, a]] is singular: recorded, yet the pentagon is still checked.
    assert_eq!(category.singular_blocks(), &[[1, 1, 1, 1]]);
    let defects = category.pentagon_defects();
    let expected = vec![
        [1, 1, 1, 1, 0, 0, 1, 1, 2],
        [1, 1, 1, 1, 0, 2, 1, 1, 0],
        [1, 1, 1, 1, 2, 0, 1, 1, 2],
        [1, 1, 1, 1, 2, 2, 1, 1, 0],
        [1, 1, 1, 2, 1, 2, 1, 0, 1],
        [1, 1, 1, 2, 1, 2, 1, 2, 1],
        [1, 1, 2, 1, 1, 0, 2, 2, 1],
        [1, 1, 2, 1, 1, 2, 0, 2, 1],
        [1, 2, 1, 1, 1, 1, 2, 0, 2],
        [1, 2, 1, 1, 1, 1, 2, 2, 0],
        [2, 1, 1, 1, 1, 1, 0, 1, 2],
        [2, 1, 1, 1, 1, 1, 2, 1, 2],
    ];
    assert_eq!(sorted(defects.iter().map(|d| d.labels).collect()), expected);
    // The defects come out in lexicographic order, and every one reads the perturbed entry.
    assert_eq!(
        defects.iter().map(|d| d.labels).collect::<Vec<_>>(),
        expected
    );
    assert!(defects.iter().all(|d| d.involves([1, 1, 1, 1], 2, 2)));
    assert_eq!(
        category.first_pentagon_defect().unwrap().labels,
        [1, 1, 1, 1, 0, 0, 1, 1, 2]
    );
    assert_eq!(
        category.validate(),
        Err(FusionError::Category(CategoryDefect::BlockSingular {
            labels: [1, 1, 1, 1]
        }))
    );
    // A braided category cannot be built on a singular F-block (the hexagons need its inverse).
    assert_eq!(
        BraidedFusionCategory::new(category, ising.braided().r_symbols().clone()),
        Err(FusionError::Category(CategoryDefect::BlockSingular {
            labels: [1, 1, 1, 1]
        }))
    );
}

#[test]
fn perturbed_ising_r_symbols_fail_the_hexagons_at_the_independent_tuples() {
    let ising = ising();
    let category = ising.category().clone();
    // R^{ss}_psi = zeta_16^3 -> zeta_16^-3: eight violations in both forms.
    let r = ising
        .braided()
        .r_symbols()
        .with_entry([1, 1, 2], z(-3))
        .unwrap();
    let braided = BraidedFusionCategory::new(category.clone(), r).unwrap();
    let expected = vec![
        [1, 1, 1, 1, 0, 0],
        [1, 1, 1, 1, 0, 2],
        [1, 1, 1, 1, 2, 0],
        [1, 1, 1, 1, 2, 2],
        [1, 2, 1, 0, 1, 2],
        [1, 2, 1, 2, 1, 0],
        [2, 1, 1, 0, 1, 1],
        [2, 1, 1, 2, 1, 1],
    ];
    for form in [HexagonForm::Direct, HexagonForm::Mirror] {
        let defects = braided.hexagon_defects(form);
        assert_eq!(
            defects.iter().map(|d| d.labels).collect::<Vec<_>>(),
            expected
        );
        assert!(defects.iter().all(|d| d.reads_r([1, 1, 2])));
    }
    // R^{s psi}_s = -i -> +i is invisible to the direct hexagon but not to the mirror one:
    // the two forms are genuinely different equations.
    let r = ising
        .braided()
        .r_symbols()
        .with_entry([1, 2, 1], i_unit())
        .unwrap();
    let braided = BraidedFusionCategory::new(category, r).unwrap();
    assert!(braided.hexagon_defects(HexagonForm::Direct).is_empty());
    let mirror = braided.hexagon_defects(HexagonForm::Mirror);
    assert_eq!(
        sorted(mirror.iter().map(|d| d.labels).collect()),
        vec![
            [1, 1, 1, 1, 2, 0],
            [1, 1, 1, 1, 2, 2],
            [1, 2, 1, 0, 1, 2],
            [1, 2, 1, 2, 1, 0],
            [2, 1, 1, 0, 1, 1],
            [2, 1, 1, 2, 1, 1],
        ]
    );
    assert!(matches!(
        braided.validate(),
        Err(FusionError::Braided(
            core_fusion_categories::braided::BraidedDefect::Hexagon { mirror: true, .. }
        ))
    ));
}

#[test]
fn ising_braid_generators_are_the_clifford_gates_exactly() {
    let ising = ising();
    let generators = ising.braid_generators(1, 4, 0).unwrap();
    assert_eq!(generators.len(), 3);
    let phase = z(-1);
    // sigma_1 = zeta_16^-1 S and sigma_2 = zeta_16^-1 H S H, sigma_3 = sigma_1, exactly.
    let s = s_gate();
    let h = hadamard();
    let hsh = matrix::multiply(
        &matrix::multiply(&h, &s).map_err(FusionError::from).unwrap(),
        &h,
    )
    .map_err(FusionError::from)
    .unwrap();
    assert_eq!(
        generators[0],
        matrix::scale(&s, &phase)
            .map_err(FusionError::from)
            .unwrap()
    );
    assert_eq!(
        generators[1],
        matrix::scale(&hsh, &phase)
            .map_err(FusionError::from)
            .unwrap()
    );
    assert_eq!(generators[2], generators[0]);
    assert_eq!(braid_relation_defects(&generators).unwrap(), vec![]);
    // The full twist is the scalar theta_1 / theta_sigma^4 = zeta_16^-4.
    let twist = ising.full_twist(1, 4, 0).unwrap();
    assert_eq!(
        twist,
        matrix::scale(
            &matrix::identity::<K>(2).map_err(FusionError::from).unwrap(),
            &z(-4)
        )
        .map_err(FusionError::from)
        .unwrap()
    );
    assert_eq!(ising.full_twist_scalar(1, 4, 0).unwrap(), z(-4));
}

#[test]
fn the_ising_braid_image_is_the_clifford_group_with_eight_scalars_and_no_t_gate() {
    let ising = ising();
    let generators = ising.braid_generators(1, 4, 0).unwrap();
    // The exact group: 192 elements = 24 (Clifford group modulo scalars) x 8 scalars zeta_8^k.
    let full = group_closure(&generators, 1000, false).unwrap();
    assert_eq!(full.order(), Some(192));
    let projective = group_closure(&generators, 1000, true).unwrap();
    assert_eq!(projective.order(), Some(24));
    let ClosureOutcome::Finite(group) = projective else {
        panic!("the projective Ising braid image is finite");
    };
    let x = matrix::from_rows(vec![vec![K::zero(), K::one()], vec![K::one(), K::zero()]])
        .map_err(FusionError::from)
        .unwrap();
    let t_gate = matrix::diagonal(&[K::one(), z(2)])
        .map_err(FusionError::from)
        .unwrap();
    assert!(group.contains(&s_gate()).unwrap());
    assert!(group.contains(&hadamard()).unwrap());
    assert!(group.contains(&x).unwrap());
    assert!(
        !group.contains(&t_gate).unwrap(),
        "T = diag(1, zeta_8) is not in the exact braid image"
    );
    // The bound is an honest bound: a too-small one reports ExceedsBound, not a wrong order.
    assert!(matches!(
        group_closure(&generators, 100, false).unwrap(),
        ClosureOutcome::ExceedsBound { bound: 100 }
    ));
}

/// The Jordan-Wigner Majoranas on two qubits (Paulis over `Q(i) inside Q(zeta_16)`), their
/// braid operators `(1 - gamma_i gamma_{i+1}) / sqrt 2` restricted to the even-parity
/// sector `{|00>, |11>}`.
#[test]
fn the_majorana_algebra_is_an_independent_witness_for_the_anyon_braid_generators() {
    let identity = matrix::identity::<K>(2).map_err(FusionError::from).unwrap();
    let pauli_x = matrix::from_rows(vec![vec![K::zero(), K::one()], vec![K::one(), K::zero()]])
        .map_err(FusionError::from)
        .unwrap();
    let pauli_y = matrix::from_rows(vec![
        vec![K::zero(), i_unit().neg()],
        vec![i_unit(), K::zero()],
    ])
    .map_err(FusionError::from)
    .unwrap();
    let pauli_z = matrix::diagonal(&[K::one(), K::one().neg()])
        .map_err(FusionError::from)
        .unwrap();
    let kron = |a: &BasicMatrix<K>, b: &BasicMatrix<K>| {
        matrix::kronecker(a, b).map_err(FusionError::from).unwrap()
    };
    let gamma = [
        kron(&pauli_x, &identity),
        kron(&pauli_y, &identity),
        kron(&pauli_z, &pauli_x),
        kron(&pauli_z, &pauli_y),
    ];
    // The Clifford relations gamma_i gamma_j + gamma_j gamma_i = 2 delta_ij.
    for i in 0..4 {
        for j in 0..4 {
            let anticommutator = matrix::add(
                &matrix::multiply(&gamma[i], &gamma[j])
                    .map_err(FusionError::from)
                    .unwrap(),
                &matrix::multiply(&gamma[j], &gamma[i])
                    .map_err(FusionError::from)
                    .unwrap(),
            )
            .map_err(FusionError::from)
            .unwrap();
            let expected = if i == j {
                matrix::scale(
                    &matrix::identity::<K>(4).map_err(FusionError::from).unwrap(),
                    &from_i64::<K>(2),
                )
                .map_err(FusionError::from)
                .unwrap()
            } else {
                matrix::zeros::<K>(4, 4).map_err(FusionError::from).unwrap()
            };
            assert_eq!(anticommutator, expected, "{{gamma_{i}, gamma_{j}}}");
        }
    }
    // The even-parity sector is spanned by |00> (index 0) and |11> (index 3).
    let inverse_sqrt2 = inverse_sqrt_two();
    let identity4 = matrix::identity::<K>(4).map_err(FusionError::from).unwrap();
    let even_sector = [0usize, 3];
    let restrict = |m: &BasicMatrix<K>| -> BasicMatrix<K> {
        matrix::from_rows(
            even_sector
                .iter()
                .map(|&r| even_sector.iter().map(|&c| m.get(r, c).unwrap()).collect())
                .collect(),
        )
        .map_err(FusionError::from)
        .unwrap()
    };
    let generators = ising().braid_generators(1, 4, 0).unwrap();
    for (index, generator) in generators.iter().enumerate() {
        let product = matrix::multiply(&gamma[index], &gamma[index + 1])
            .map_err(FusionError::from)
            .unwrap();
        // The operator exp(-(pi/4) gamma_i gamma_{i+1}) = (1 - gamma_i gamma_{i+1}) / sqrt 2.
        let braid_inverse = matrix::scale(
            &matrix::sub(&identity4, &product)
                .map_err(FusionError::from)
                .unwrap(),
            &inverse_sqrt2,
        )
        .map_err(FusionError::from)
        .unwrap();
        // It preserves the even sector (commutes with the parity Z (x) Z).
        let parity = kron(&pauli_z, &pauli_z);
        assert_eq!(
            matrix::multiply(&braid_inverse, &parity)
                .map_err(FusionError::from)
                .unwrap(),
            matrix::multiply(&parity, &braid_inverse)
                .map_err(FusionError::from)
                .unwrap()
        );
        // sigma_i = zeta_16 * (braid operator)^-1 restricted to the even sector.
        let witness = matrix::scale(&restrict(&braid_inverse), &z(1))
            .map_err(FusionError::from)
            .unwrap();
        assert_eq!(
            generator,
            &witness,
            "sigma_{} against the Majorana braid",
            index + 1
        );
    }
}

#[test]
fn ising_braid_relations_hold_on_mixed_words_with_psi_and_the_unit() {
    let ising = ising();
    // Words of distinct letters make the exchange maps go between different spaces.
    for (word, total) in [
        (vec![1usize, 2, 1], 2usize),
        (vec![2, 1, 1], 2),
        (vec![1, 1, 2], 0),
        (vec![1, 2, 1, 1], 1),
        (vec![2, 1, 1, 2, 1], 1),
        (vec![1, 0, 1, 1], 1),
        (vec![2, 2, 1, 1, 0], 0),
    ] {
        let space = ising.braided().fusion_space(&word, total).unwrap();
        assert!(
            space.dimension() > 0,
            "{word:?} -> {total} is a nonzero space"
        );
        assert_eq!(
            ising
                .braided()
                .braid_relation_defects_on_word(&word, total)
                .unwrap(),
            vec![],
            "{word:?} -> {total}"
        );
    }
    // sigma then psi: the exchange of sigma and psi on Hom(sigma, sigma psi) is the scalar
    // R^{sigma psi}_sigma = -i, and exchanging back gives the monodromy R^{sigma psi} R^{psi sigma} = -1.
    let space = ising.braided().fusion_space(&[1, 2], 1).unwrap();
    let (swapped, forward) = ising.braided().braid_matrix(&space, 1).unwrap();
    let (_, back) = ising.braided().braid_matrix(&swapped, 1).unwrap();
    assert_eq!(forward.get(0, 0).unwrap(), i_unit().neg());
    assert_eq!(
        matrix::multiply(&back, &forward)
            .map_err(FusionError::from)
            .unwrap()
            .get(0, 0)
            .unwrap(),
        K::one().neg()
    );
}

